<template><div class="page-shell"><header class="page-header"><p class="eyebrow">Mastery XP</p><h1>Leaderboard</h1><p>See your classroom first, then compare progress across Math Practice.</p></header><div class="tabs" role="tablist"><button :class="{active:scope==='class'}" @click="change('class')">My class</button><button :class="{active:scope==='global'}" @click="change('global')">Global</button></div><p v-if="error" class="error-state">{{error}}</p><div class="board glass-card"><div class="board-head"><span>Rank</span><span>Learner</span><span>Grade</span><span>XP</span></div><div v-for="entry in entries" :key="entry.username" class="board-row"><b>#{{entry.rank}}</b><strong>{{entry.username}}</strong><span>{{entry.grade||'—'}}</span><em>{{entry.xp}}</em></div><div v-if="!entries.length&&!error" class="empty-state">No rankings yet. Complete a practice session to begin.</div></div></div></template>
<script>import{api}from'../api';export default{name:'Leaderboard',data:()=>({scope:'class',entries:[],error:''}),created(){document.title='Leaderboard · Math Practice';this.load()},methods:{async load(){this.error='';try{this.entries=await api(`/api/leaderboards?scope=${this.scope}`)}catch(e){this.error=this.scope==='class'?'Join a class to view classroom rankings.':e.message;this.entries=[]}},change(scope){this.scope=scope;this.load()}}}</script>
<style scoped>.tabs{display:flex;gap:.5rem;margin-bottom:1rem}.tabs button{padding:.7rem 1rem;border-radius:999px;border:1px solid hsl(var(--clr-white-200)/.15);background:transparent;color:var(--clr-text);cursor:pointer}.tabs button.active{background:hsl(var(--clr-primary-400));border-color:hsl(var(--clr-accent-200)/.5)}.board{overflow:hidden;margin-bottom:4rem}.board-head,.board-row{display:grid;grid-template-columns:.5fr 2fr 1fr 1fr;gap:1rem;padding:1rem 1.4rem}.board-head{font:700 .72rem var(--ff-mono);text-transform:uppercase;color:hsl(var(--clr-white-600))}.board-row{border-top:1px solid hsl(var(--clr-white-200)/.1);align-items:center}.board-row>b{color:hsl(var(--clr-secondary-200));font:800 1.3rem var(--ff-serif)}.board-row em{font-style:normal;color:hsl(var(--clr-accent-200));font-weight:800}</style>
